def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    active = [any(x != bg for x in row) for row in grid]

    # Separate the foreground patterns into bands divided by blank rows.
    bands = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        bands.append((start, r))

    out = [row[:] for row in grid]
    for start, end in bands:
        for rr in range(start, end):
            # Only consider the blank suffix after the row's last foreground cell.
            fgcols = [c for c, x in enumerate(grid[rr]) if x != bg]
            if not fgcols:
                continue
            first = fgcols[-1] + 1
            if first >= w:
                continue
            length = w - first

            # Compare this row with rows at the same offset in the other bands.
            covered = [False] * length
            for s2, e2 in bands:
                if (s2, e2) == (start, end):
                    continue
                r2 = s2 + (rr - start)
                if r2 >= e2:
                    continue
                for j, c in enumerate(range(first, w)):
                    if grid[r2][c] != bg:
                        covered[j] = True

            # Avoid marking isolated coincidences in a long suffix.
            if sum(covered) * 2 >= length:
                for j, c in enumerate(range(first, w)):
                    if covered[j]:
                        out[rr][c] = 1

    return out
